import fs from 'node:fs';
import path from 'node:path';

import { profile } from '../profile';

export const codegenHeader = `/**
 * DO NOT MODIFY
 * @danger This file is generated by the ${profile.scriptName} script.
*/`;

const STRING_ESCAPES: Record<string, string> = {
  '\\': '\\\\',
  "'": "\\'",
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
};

/** Escapes what could end a single-quoted string or break its line: the backslash, the quote and the control characters. */
const escapeString = (text: string) =>
  text.replace(
    /[\\'\p{Cc}\u2028\u2029]/gu,
    (char) => STRING_ESCAPES[char] ?? `\\u${char.charCodeAt(0).toString(16).padStart(4, '0')}`,
  );

/**
 * A value as a TypeScript literal, laid out like `JSON.stringify(value, null, 2)` but with
 * single-quoted strings, the style of the generated files. Every string is escaped, so that no
 * text in it (a description from Figma, say) can end the string and become code.
 */
export const toSingleQuotedLiteral = (value: unknown, indent = ''): string => {
  const inner = `${indent}  `;
  if (typeof value === 'string') return `'${escapeString(value)}'`;
  if (Array.isArray(value)) {
    if (value.length === 0) return '[]';
    const items = value.map((item) => `${inner}${toSingleQuotedLiteral(item, inner)}`);
    return `[\n${items.join(',\n')}\n${indent}]`;
  }
  if (value !== null && typeof value === 'object') {
    // Like JSON, an entry without a value is left out.
    const entries = Object.entries(value).filter(([, entry]) => entry !== undefined);
    if (entries.length === 0) return '{}';
    const lines = entries.map(
      ([key, entry]) =>
        `${inner}${toSingleQuotedLiteral(key)}: ${toSingleQuotedLiteral(entry, inner)}`,
    );
    return `{\n${lines.join(',\n')}\n${indent}}`;
  }
  return JSON.stringify(value) ?? 'undefined';
};

export const writeFile = (filePath: string, content: string | Uint8Array) =>
  fs.writeFileSync(filePath, content);

/** Replaces a directory with an empty one. */
export const resetDirectory = (directory: string) => {
  if (fs.existsSync(directory)) fs.rmSync(directory, { recursive: true });
  fs.mkdirSync(directory, { recursive: true });
};

/** Resolves an SVG path, or undefined if the name escapes `outputSvgPath`. */
export const resolveSvgPath = (outputSvgPath: string, svgName: string): string | undefined => {
  const root = path.resolve(outputSvgPath);
  const resolved = path.resolve(root, `${svgName}.svg`);
  return resolved.startsWith(root + path.sep) ? resolved : undefined;
};
